const conf = readConfig();
const pProxy = await probe("proxy");
const pBackend = await probe("backend");
const pUpstream = await probe("configuredUpstream");
const result = {
  config: conf,
  proxy: pProxy,
  backend: pBackend,
  configuredUpstream: pUpstream,
  finding: conf.proxyPort === conf.upstreamPort ? "Ports match" : "Proxy upstream port mismatch detected"
};
console.log(JSON.stringify(result));
